"""
STEP 2 - Clean text columns.

Input:
    outputs/step1_no_duplicates.csv

Output:
    outputs/step2_clean_text.csv

Run after step 1.
"""

from pathlib import Path

import numpy as np
import pandas as pd

BASE_DIR = Path(__file__).resolve().parent
INPUT_FILE = BASE_DIR / "outputs" / "step1_no_duplicates.csv"
OUTPUT_DIR = BASE_DIR / "outputs"
OUTPUT_DIR.mkdir(exist_ok=True)

# Load the output generated by step 1.
df = pd.read_csv(INPUT_FILE)

# Inspect city values before cleaning.
print("City values BEFORE:", df["city"].unique())

# Remove leading/trailing spaces and standardise names.
df["name"] = df["name"].str.strip().str.title()

# Standardise department names. Restore the acronym HR after title-casing.
df["department"] = (
    df["department"]
    .str.strip()
    .str.title()
    .replace({"Hr": "HR"})
)

# Map alternate city spellings to one standard city name.
city_map = {
    "bengaluru": "Bangalore",
    "new delhi": "Delhi",
}

df["city"] = (
    df["city"]
    .str.strip()
    .str.lower()
    .replace(city_map)
    .str.title()
)

print("City values AFTER:", df["city"].unique())

# Save the cleaned text data for step 3.
output_file = OUTPUT_DIR / "step2_clean_text.csv"
df.to_csv(output_file, index=False)
print(f"Saved: {output_file}")
